'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var isComplexLike = require( '@stdlib/assert/is-complex-like' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var factory = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function for complex128.
*
* @private
* @param {Complex128} a - first value
* @param {Complex128} b - second value
* @returns {number} comparison result
*/
function compareFcn128( a, b ) {
	var re1;
	var re2;
	var im1;
	var im2;
	re1 = real( a );
	re2 = real( b );
	if ( re1 < re2 ) {
		return -1;
	}
	if ( re1 > re2 ) {
		return 1;
	}
	im1 = imag( a );
	im2 = imag( b );
	if ( im1 < im2 ) {
		return -1;
	}
	if ( im1 > im2 ) {
		return 1;
	}
	return 0;
}

/**
* Comparison function for complex64.
*
* @private
* @param {Complex64} a - first value
* @param {Complex64} b - second value
* @returns {number} comparison result
*/
function compareFcn64( a, b ) {
	var re1;
	var re2;
	var im1;
	var im2;
	re1 = realf( a );
	re2 = realf( b );
	if ( re1 < re2 ) {
		return -1;
	}
	if ( re1 > re2 ) {
		return 1;
	}
	im1 = imagf( a );
	im2 = imagf( b );
	if ( im1 < im2 ) {
		return -1;
	}
	if ( im1 > im2 ) {
		return 1;
	}
	return 0;
}

/**
* Creates a benchmark function for complex128.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark128( len ) {
	var Complex128Array;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = [];
	for ( i = 0; i < len; i++ ) {
		arr.push( new Complex128( i, i ) );
	}
	arr = new Complex128Array( arr );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = arr.sort( compareFcn128 );
			if ( typeof out !== 'object' ) {
				b.fail( 'should return an object' );
			}
		}
		b.toc();
		if ( !isComplexLike( out.get( 0 ) ) ) {
			b.fail( 'should return a complex array' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}

/**
* Creates a benchmark function for complex64.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark64( len ) {
	var Complex64Array;
	var arr;
	var i;

	Complex64Array = factory( 'complex64' );
	arr = [];
	for ( i = 0; i < len; i++ ) {
		arr.push( new Complex64( i, i ) );
	}
	arr = new Complex64Array( arr );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = arr.sort( compareFcn64 );
			if ( typeof out !== 'object' ) {
				b.fail( 'should return an object' );
			}
		}
		b.toc();
		if ( !isComplexLike( out.get( 0 ) ) ) {
			b.fail( 'should return a complex array' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var f;
	var i;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark128( len );
		bench( format( '%s::complex128:sort:len=%d', pkg, len ), f );
	}
	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark64( len );
		bench( format( '%s::complex64:sort:len=%d', pkg, len ), f );
	}
}

main();
